(() => {
  const shown = () => document.querySelector('main')?.innerText ?? '';
  window.__openRows = [...document.querySelectorAll('[aria-label$=" 的操作"]')]
    .map(el => el.getAttribute('aria-label').replace(/ 的操作$/, ''))
    .filter(title => title.length <= 16 && !shown().includes(title));
  return window.__openRows.length;
})()

(() => {
  window.__openSamples = { cold: [], warm: [] };
  window.__lafMs = [];
  window.__openBuild = [...document.querySelectorAll('script[type="module"]')]
    .some(script => /\/shot\//.test(script.src)) ? "dev" : "production";
  try {
    new PerformanceObserver((list) => {
      for (const entry of list.getEntries()) window.__lafMs.push(Math.round(entry.duration));
    }).observe({ type: "long-animation-frame" });
  } catch {}
  const mainText = () => document.querySelector("main")?.innerText ?? "";
  window.__armOpen = (phase, label, marker) => {
    window.__openPromise = new Promise((resolve) => {
      let start = -1;
      let clickMs = -1;
      let titleMs = -1;
      const finish = (timedOut) => {
        observer.disconnect();
        const sample = {
          phase,
          label,
          pressToClickMs: clickMs,
          titleMs,
          contentMs: timedOut ? -1 : Math.round(performance.now() - start),
          timedOut,
        };
        (window.__openSamples[phase] ??= []).push(sample);
        resolve(sample);
      };
      const check = () => {
        if (start < 0) return false;
        const text = mainText();
        if (titleMs < 0 && text.includes(label)) titleMs = Math.round(performance.now() - start);
        if (text.includes(marker)) { finish(false); return true; }
        return false;
      };
      const observer = new MutationObserver(() => { check(); });
      window.addEventListener("click", () => {
        if (start >= 0 && clickMs < 0) clickMs = Math.round((performance.now() - start) * 10) / 10;
      }, { capture: true, once: true });
      window.addEventListener("pointerdown", () => {
        start = performance.now();
        observer.observe(document.body, { subtree: true, childList: true, characterData: true });
        check();
        setTimeout(() => { if (start >= 0) finish(true); }, 20000);
      }, { capture: true, once: true });
    });
    return true;
  };
  return true;
})()

(() => {
  const median = (values) => {
    if (!values.length) return null;
    const sorted = [...values].sort((a, b) => a - b);
    const middle = Math.floor(sorted.length / 2);
    return Math.round(sorted.length % 2 ? sorted[middle] : (sorted[middle - 1] + sorted[middle]) / 2);
  };
  const pure = (samples) => samples.filter(sample => !sample.timedOut);
  const cold = pure(window.__openSamples.cold);
  const warm = pure(window.__openSamples.warm);
  const build = window.__openBuild;
  window.__openSummary = {
    build,
    coldSamples: cold.length,
    warmSamples: warm.length,
    coldMs: cold.map(s => s.contentMs),
    warmMs: warm.map(s => s.contentMs),
    coldTitleMs: cold.map(s => s.titleMs),
    pressToClickMs: [...cold, ...warm].map(s => s.pressToClickMs),
    coldMedian: median(cold.map(s => s.contentMs)),
    warmMedian: median(warm.map(s => s.contentMs)),
    coldTitleMedian: median(cold.map(s => s.titleMs)),
    coldMax: cold.length ? Math.max(...cold.map(s => s.contentMs)) : null,
    warmMax: warm.length ? Math.max(...warm.map(s => s.contentMs)) : null,
    pressToClickMax: Math.max(...[...cold, ...warm].map(s => s.pressToClickMs ?? 0)),
    timedOut: window.__openSamples.cold.length + window.__openSamples.warm.length - cold.length - warm.length,
    lafMax: window.__lafMs.length ? Math.max(...window.__lafMs) : 0,
    lafCount: window.__lafMs.length,
    limits: {
      cold: build === "dev" ? 320 : 90,
      warm: build === "dev" ? 200 : 40,
      laf: build === "dev" ? 250 : 50,
    },
  };
  return window.__openSummary;
})()
